begin;
create table wm.catalog_registry (
 catalog_id text not null,variant text not null,catalog_version text not null,snapshot jsonb not null,digest text not null,
 primary key(catalog_id,variant,catalog_version),check(digest=wm.hash_json(snapshot))
);
alter table wm.catalog_registry enable row level security;
revoke all on wm.catalog_registry from public,anon,authenticated;
create trigger immutable_history before update or delete on wm.catalog_registry for each row execute function wm.reject_history_edit();
alter table wm.agreements add column sent_at timestamptz,add column accepted_at timestamptz,add column signer_name text,add column effective_state text not null default 'pending' check(effective_state in ('pending','effective','replaced'));
alter table wm.milestones add column proof_kind text not null default 'approved_work' check(proof_kind in ('booking','readiness','approved_work','verified_launch'));
create table wm.intro_care_slots(slot integer primary key check(slot between 1 and 3),organization_id uuid,agreement_id uuid,expires_at timestamptz,consumed_at timestamptz,foreign key(organization_id,agreement_id) references wm.agreements(organization_id,id));
insert into wm.intro_care_slots(slot) values(1),(2),(3);
alter table wm.intro_care_slots enable row level security;
revoke all on wm.intro_care_slots from public,anon,authenticated;
create index intro_care_agreement on wm.intro_care_slots(organization_id,agreement_id);
alter table wm.milestones add column evidence text,add column evidence_request_id uuid,
 add foreign key(organization_id,engagement_id,evidence_request_id) references wm.requests(organization_id,engagement_id,id);
create unique index one_milestone_work on wm.milestones(organization_id,evidence_request_id) where evidence_request_id is not null;
create index milestones_evidence_parent on wm.milestones(organization_id,engagement_id,evidence_request_id);
create function wm.protect_agreement() returns trigger language plpgsql set search_path='' as $$
begin
 if old.accepted_at is not null and (to_jsonb(new)-array['status','version','effective_state']) is distinct from (to_jsonb(old)-array['status','version','effective_state']) then raise exception 'Accepted agreement evidence is immutable' using errcode='42501';end if;
 return new;
end $$;
create trigger protect_agreement before update on wm.agreements for each row execute function wm.protect_agreement();

drop index wm.one_billing_component;
create unique index one_billing_component on wm.billing_schedules(organization_id,engagement_id,component) where effective_until is null and state not in ('planned','replacement_pending','cancelled');

create function public.wm_commercial_command(p_org uuid,p_command text,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare result jsonb; cat wm.catalog_registry; e wm.engagements;a wm.agreements;prior wm.agreements;r wm.requests;rev wm.revisions;authz wm.engagement_authorities;
 snap jsonb;item jsonb;sid uuid;rid uuid;v bigint;did uuid;receipt uuid;start_at timestamptz;amount bigint;cap text;mil wm.milestones;access wm.access_requirements;period_end timestamptz; slot_id integer;
begin
 cap:=case when p_command='agreement.accept' then 'write' when p_command in ('onboarding.update','milestone.complete','milestone.link','service.start') then 'delivery' else 'finance' end;
 perform wm.require_access(p_org,cap);
 result:=wm.prior_command(p_org,p_command,p_key,p_input);if result is not null then return result;end if;
 if p_command in ('service.create','proposal.create') then
  select * into cat from wm.catalog_registry where catalog_id=p_input->>'catalog_id' and variant=p_input->>'variant' and catalog_version=p_input->>'catalog_version';
  if not found then raise exception 'Choose a current catalog service and variant' using errcode='22023';end if;
 end if;
 if p_command='service.create' then
  perform wm.check_input(p_input,array['catalog_id','variant','catalog_version','title'],array['catalog_id','variant','catalog_version','title']);
  insert into wm.engagements(organization_id,service_type,catalog_id,catalog_version,title,owner_user_id,created_by)
   values(p_org,cat.snapshot->>'service_type',cat.catalog_id,cat.catalog_version,wm.require_text(p_input->>'title','service name',160),auth.uid(),auth.uid()) returning id,version into rid,v;
  return wm.finish_command(p_org,p_command,p_key,p_input,jsonb_build_object('id',rid,'version',v),rid);
 end if;
 if p_command='proposal.create' then
  perform wm.check_input(p_input,array['engagement_id','catalog_id','variant','catalog_version','expected_version','starts_at','scope_note','quote_minor','waiver_evidence','waiver_kind','waiver_agreement_id','supersedes_id'],array['engagement_id','catalog_id','variant','catalog_version','expected_version','starts_at','scope_note']);
  select * into e from wm.engagements where organization_id=p_org and id=(p_input->>'engagement_id')::uuid for update;
  if not found or e.catalog_id<>cat.catalog_id or e.service_type<>cat.snapshot->>'service_type' or e.service_state in ('ending','closed') then raise exception 'Choose the matching current service' using errcode='42501';end if;
  perform wm.check_version(e.version,(p_input->>'expected_version')::bigint);
  if exists(select 1 from wm.agreements where organization_id=p_org and engagement_id=e.id and status in ('draft','sent')) then raise exception 'Withdraw the outstanding proposal before replacing it' using errcode='40001';end if;
  if p_input->>'supersedes_id' is not null then
   select * into prior from wm.agreements where organization_id=p_org and engagement_id=e.id and id=(p_input->>'supersedes_id')::uuid and status='accepted' and not exists(select 1 from wm.agreements newer where newer.organization_id=p_org and newer.supersedes_id=(p_input->>'supersedes_id')::uuid and newer.status='accepted');
   if not found then raise exception 'Choose the accepted agreement to amend' using errcode='42501';end if;
  elsif exists(select 1 from wm.agreements where organization_id=p_org and engagement_id=e.id and status='accepted') then raise exception 'An amendment must name the accepted agreement' using errcode='22023';end if;
  start_at:=(p_input->>'starts_at')::timestamptz;
  if start_at<date_trunc('day',now()) then raise exception 'Choose a current proposed start date' using errcode='22023';end if;
  snap:=cat.snapshot||jsonb_build_object('scope_note',wm.require_text(p_input->>'scope_note','agreed scope',12000),'proposed_start',start_at);
  if (snap->>'quote_required')::boolean then
   amount:=(p_input->>'quote_minor')::bigint;if amount is null or amount not between 1 and 100000000 then raise exception 'Enter the written fixed quote' using errcode='22023';end if;
   snap:=snap||jsonb_build_object('milestones',jsonb_build_array(jsonb_build_object('id','stage_1','deliverable','Book the agreed scope','acceptance_rule','Book the agreed scope','amount_minor',amount/2,'proof','booking'),jsonb_build_object('id','stage_2','deliverable','Accept the agreed deliverables','acceptance_rule','Accept the agreed deliverables','amount_minor',amount-amount/2,'proof','approved_work')));
  elsif p_input ? 'quote_minor' then raise exception 'Catalog prices cannot be overwritten' using errcode='22023';end if;
  if p_input->>'waiver_evidence' is not null and p_input->>'waiver_kind' is null then raise exception 'Choose the catalog waiver eligibility' using errcode='22023';end if;
  if p_input->>'waiver_kind' is not null then
   perform wm.require_text(p_input->>'waiver_evidence','verified onboarding waiver',2000);
   if not exists(select 1 from jsonb_array_elements(snap->'components') c where c->>'id'='care_onboarding') then raise exception 'This service has no onboarding charge to waive' using errcode='22023';end if;
   if p_input->>'waiver_kind'='post_build' then
    if not exists(select 1 from wm.agreements source_agreement join wm.engagements source_engagement on source_engagement.organization_id=p_org and source_engagement.id=source_agreement.engagement_id
     where source_agreement.organization_id=p_org and source_agreement.id=(p_input->>'waiver_agreement_id')::uuid and source_agreement.accepted_at is not null and source_engagement.service_type='web_design'
     and exists(select 1 from wm.website_releases w join wm.requests q on q.organization_id=p_org and q.id=w.request_id where w.organization_id=p_org and q.engagement_id=source_engagement.id and w.status='verified' and w.created_at>now()-interval '30 days')) then raise exception 'A recent verified W&M build handoff is required' using errcode='42501';end if;
   elsif p_input->>'waiver_kind'='intro_production' and cat.catalog_id in ('improve','local_focus','grow') then
    perform pg_advisory_xact_lock(173105);
    if exists(select 1 from wm.intro_care_slots where organization_id=p_org and (consumed_at is not null or expires_at>now())) then raise exception 'This business already has an introductory place' using errcode='22023';end if;
    select slot into slot_id from wm.intro_care_slots where consumed_at is null and (agreement_id is null or expires_at<=now()) order by slot limit 1 for update;
    if slot_id is null then raise exception 'All three introductory Care places are allocated' using errcode='40001';end if;
   else raise exception 'Choose an eligible onboarding waiver' using errcode='22023';end if;
   snap:=jsonb_set(snap,'{components}',(select jsonb_agg(case when c->>'id'='care_onboarding' then c||jsonb_build_object('amount_minor',0,'waiver_evidence',p_input->>'waiver_evidence','verified_by',auth.uid(),'waiver_kind',p_input->>'waiver_kind','source_agreement_id',p_input->>'waiver_agreement_id','reserved_intro_slot',slot_id) else c end) from jsonb_array_elements(snap->'components') c));
  end if;
  insert into wm.catalog_snapshots(organization_id,catalog_id,catalog_version,snapshot,digest,created_by) values(p_org,cat.catalog_id,cat.catalog_version,snap,wm.hash_json(snap),auth.uid()) on conflict(organization_id,catalog_id,digest) do nothing;
  select id into sid from wm.catalog_snapshots where organization_id=p_org and catalog_id=cat.catalog_id and digest=wm.hash_json(snap);
  insert into wm.requests(organization_id,engagement_id,outcome,state,accepted_scope,coverage,owner_user_id,due_at,next_contact_at,created_by)
   values(p_org,e.id,'Agreement: '||(snap->>'name'),'accepted',p_input->>'scope_note','Written proposal',auth.uid(),start_at,now()+interval '1 day',auth.uid()) returning * into r;
  insert into wm.revisions(organization_id,request_id,sequence,kind,manifest,digest,summary,cost_effect,date_effect,created_by)
   values(p_org,r.id,1,'agreement',snap,wm.hash_json(snap),snap->>'name','Exact fees and schedule in this agreement','Proposed start: '||start_at::text,auth.uid()) returning * into rev;
  update wm.requests set current_revision_id=rev.id where organization_id=p_org and id=r.id;
  insert into wm.agreements(organization_id,engagement_id,request_id,revision_id,catalog_snapshot_id,starts_at,supersedes_id,created_by)
   values(p_org,e.id,r.id,rev.id,sid,start_at,prior.id,auth.uid()) returning id,version into rid,v;
  if slot_id is not null then update wm.intro_care_slots set organization_id=p_org,agreement_id=rid,expires_at=now()+interval '7 days' where slot=slot_id;end if;
  update wm.engagements set version=version+1 where organization_id=p_org and id=e.id;
 elsif p_command in ('proposal.send','proposal.withdraw','agreement.accept') then
  perform wm.check_input(p_input,array['id','expected_version','digest','consent','signer_name','reason'],array['id','expected_version']);
  select * into a from wm.agreements where organization_id=p_org and id=(p_input->>'id')::uuid for update;
  if not found then raise exception 'Agreement unavailable' using errcode='42501';end if;
  perform wm.check_version(a.version,(p_input->>'expected_version')::bigint);
  select * into e from wm.engagements where organization_id=p_org and id=a.engagement_id for update;
  select * into rev from wm.revisions where organization_id=p_org and id=a.revision_id;
  if p_command='proposal.send' then
   if a.status<>'draft' then raise exception 'Only a draft can be sent' using errcode='40001';end if;
   if not exists(select 1 from wm.engagement_authorities z join wm.memberships m on m.organization_id=z.organization_id and m.user_id=z.user_id where z.organization_id=p_org and z.engagement_id=e.id and z.domain='contract' and z.revoked_at is null and z.starts_at<=now() and z.ends_at>now() and m.status='active' and m.role in ('customer_admin','contributor')) then raise exception 'Verify a named contract signer before sending' using errcode='42501';end if;
   update wm.agreements set status='sent',sent_at=now(),version=version+1 where organization_id=p_org and id=a.id returning id,version into rid,v;
   update wm.requests set state='in_review',version=version+1 where organization_id=p_org and id=a.request_id;
   -- The existing message notification outbox handles verified recipients.
   insert into wm.messages(organization_id,engagement_id,request_id,direction,visibility,sender_user_id,body) values(p_org,e.id,a.request_id,'workspace','shared',auth.uid(),'Your agreement is ready. Review the saved scope, fees, and dates in your workspace before accepting.');
  elsif p_command='proposal.withdraw' then
   if a.status not in ('draft','sent') then raise exception 'Accepted terms require an amendment or service closure' using errcode='40001';end if;
   perform wm.require_text(p_input->>'reason','withdrawal reason');
   update wm.intro_care_slots set organization_id=null,agreement_id=null,expires_at=null where organization_id=p_org and agreement_id=a.id and consumed_at is null;
   update wm.agreements set status='superseded',version=version+1 where organization_id=p_org and id=a.id returning id,version into rid,v;
   update wm.requests set state='changes_requested',waiting_reason=p_input->>'reason',version=version+1 where organization_id=p_org and id=a.request_id;
   perform wm.critical(p_org,'proposal.withdrawn',a.id,jsonb_build_object('agreement_id',a.id,'digest',rev.digest,'reason',p_input->>'reason'));
  else
   perform wm.require_recent_auth();authz:=wm.authority(p_org,e.id,'contract');
   if a.status<>'sent' or e.service_state in ('ending','closed') or rev.digest is distinct from p_input->>'digest' then raise exception 'Review the current sent agreement' using errcode='40001';end if;
   if p_input->'consent' is distinct from 'true'::jsonb then raise exception 'Affirmative acceptance is required' using errcode='22023';end if;
   perform wm.require_text(p_input->>'signer_name','signer name',160);
   if a.supersedes_id is not null and not exists(select 1 from wm.agreements where organization_id=p_org and id=a.supersedes_id and status='accepted') then raise exception 'The previous agreement changed' using errcode='40001';end if;
   select * into r from wm.requests where organization_id=p_org and id=a.request_id;
   if r.current_revision_id<>rev.id or r.state<>'in_review' then raise exception 'Review the current agreement version' using errcode='40001';end if;
   if exists(select 1 from jsonb_array_elements(rev.manifest->'components') c where c->>'waiver_kind'='intro_production') then
    perform pg_advisory_xact_lock(173105);
    update wm.intro_care_slots set consumed_at=now() where organization_id=p_org and agreement_id=a.id and consumed_at is null and expires_at>now();
    if not found then raise exception 'The introductory reservation expired. Request a current proposal.' using errcode='40001';end if;
   end if;
   insert into wm.decisions(organization_id,request_id,revision_id,digest,actor_id,authority_id,authority_version,decision,shown_scope)
    values(p_org,r.id,rev.id,rev.digest,auth.uid(),authz.id,authz.version,'approve',rev.summary||' | Affirmative agreement acceptance by '||(p_input->>'signer_name')) returning id into did;
   update wm.agreements set status='accepted',accepted_decision_id=did,accepted_at=now(),signer_name=p_input->>'signer_name',version=version+1 where organization_id=p_org and id=a.id returning id,version into rid,v;
   update wm.requests set state='approved',version=version+1 where organization_id=p_org and id=r.id;
   -- Existing active billing is not silently replaced. Amendments are scheduled
   -- for explicit financial reconciliation at their accepted effective date.
   if a.supersedes_id is not null then
    -- The previous contract and due invoices continue until the explicit
    -- effective-date reconciliation; acceptance itself changes no old charge.
    perform wm.critical(p_org,'agreement.amendment_pending',a.id,jsonb_build_object('previous_id',a.supersedes_id,'effective_at',a.starts_at));
   end if;
   snap:=rev.manifest;
   for item in select value from jsonb_array_elements(snap->'milestones') loop
    insert into wm.milestones(organization_id,engagement_id,agreement_id,deliverable,acceptance_rule,amount_minor,currency,status,proof_kind)
     values(p_org,e.id,a.id,item->>'deliverable',item->>'acceptance_rule',(item->>'amount_minor')::bigint,snap->>'currency','planned',coalesce(item->>'proof','approved_work'));
   end loop;
   for item in select value from jsonb_array_elements(snap->'components') loop
    insert into wm.billing_schedules(organization_id,engagement_id,agreement_id,component,amount_minor,currency,interval,effective_from,cancellation_policy,state)
     values(p_org,e.id,a.id,item->>'id',(item->>'amount_minor')::bigint,snap->>'currency',item->>'interval',greatest(a.starts_at,now()),jsonb_build_object('terms',snap->'terms','trigger',item->>'trigger'),case when a.supersedes_id is null then 'planned' else 'replacement_pending' end);
   end loop;
   for item in select value from jsonb_array_elements(snap->'required_access') loop
    if not exists(select 1 from wm.access_requirements where organization_id=p_org and engagement_id=e.id and provider=item#>>'{}') then
     insert into wm.access_requirements(organization_id,engagement_id,provider,capability,next_action) values(p_org,e.id,item#>>'{}','service_delivery','Connect the client-owned account and verify the required access');
    end if;
   end loop;
   update wm.engagements set commercial_state='accepted',catalog_version=snap->>'catalog_version',version=version+1 where organization_id=p_org and id=e.id;
   receipt:=wm.critical(p_org,'agreement.accepted',a.id,jsonb_build_object('agreement_id',a.id,'revision_id',rev.id,'digest',rev.digest,'snapshot',snap,'actor_id',auth.uid(),'authority_id',authz.id,'signer_name',p_input->>'signer_name','accepted_at',now(),'decision_id',did));
  end if;
 elsif p_command='onboarding.update' then
  perform wm.check_input(p_input,array['id','expected_version','status','account_reference','evidence','next_action'],array['id','expected_version','status','next_action']);
  select * into access from wm.access_requirements where organization_id=p_org and id=(p_input->>'id')::uuid for update;
  if not found then raise exception 'Access step unavailable' using errcode='42501';end if;
  perform wm.check_version(access.version,(p_input->>'expected_version')::bigint);
  if p_input->>'status'='verified' then perform wm.require_text(p_input->>'evidence','verified access evidence');perform wm.require_text(p_input->>'account_reference','exact account');end if;
  update wm.access_requirements set status=p_input->>'status',account_reference=p_input->>'account_reference',evidence=p_input->>'evidence',next_action=wm.require_text(p_input->>'next_action','next step'),last_checked_at=now(),version=version+1 where organization_id=p_org and id=access.id returning id,version into rid,v;
 elsif p_command in ('milestone.due','milestone.complete','milestone.link') then
  perform wm.check_input(p_input,array['id','expected_version','evidence','request_id'],array['id','expected_version','evidence']);
  select * into mil from wm.milestones where organization_id=p_org and id=(p_input->>'id')::uuid for update;
  if not found then raise exception 'Milestone unavailable' using errcode='42501';end if;perform wm.check_version(mil.version,(p_input->>'expected_version')::bigint);
  if not exists(select 1 from wm.agreements where organization_id=p_org and id=mil.agreement_id and status='accepted') then raise exception 'Current accepted terms required' using errcode='42501';end if;
  perform wm.require_text(p_input->>'evidence','milestone evidence');
  if p_command='milestone.due' and exists(select 1 from wm.agreements where organization_id=p_org and id=mil.agreement_id and supersedes_id is not null and effective_state<>'effective') then raise exception 'Reconcile and activate the amendment at its effective date first' using errcode='42501';end if;
  if p_command='milestone.link' then
   if mil.proof_kind<>'approved_work' or mil.status not in ('planned','due') or mil.evidence_request_id is not null then raise exception 'Milestone cannot be linked now' using errcode='40001';end if;
   select * into r from wm.requests where organization_id=p_org and engagement_id=mil.engagement_id and id=(p_input->>'request_id')::uuid for update;
   if not found or r.current_revision_id is not null or r.state not in ('accepted','preparing') or exists(select 1 from wm.agreements where organization_id=p_org and request_id=r.id) then raise exception 'Link accepted work before preparing its review version' using errcode='42501';end if;
   update wm.milestones set evidence_request_id=r.id,version=version+1 where organization_id=p_org and id=mil.id returning id,version into rid,v;
  elsif p_command='milestone.due' then
   if mil.status<>'planned' then raise exception 'Milestone is already scheduled' using errcode='40001';end if;
   update wm.milestones set status='due',due_at=now(),evidence=p_input->>'evidence',version=version+1 where organization_id=p_org and id=mil.id returning id,version into rid,v;
   insert into wm.billing_schedules(organization_id,engagement_id,agreement_id,component,amount_minor,currency,interval,effective_from,next_invoice_at,cancellation_policy,state)
    values(p_org,mil.engagement_id,mil.agreement_id,'milestone:'||mil.id,mil.amount_minor,mil.currency,'once',now(),now(),jsonb_build_object('earned_when',mil.acceptance_rule),'due');
  else
   if mil.status<>'due' then raise exception 'Start the milestone before completing it' using errcode='40001';end if;
   if mil.proof_kind='approved_work' and (p_input->>'request_id' is null or mil.evidence_request_id is null or mil.evidence_request_id<>(p_input->>'request_id')::uuid) then raise exception 'Approved delivered work is required for this milestone' using errcode='42501';end if;
   if p_input->>'request_id' is not null and not exists(select 1 from wm.requests q where q.organization_id=p_org and q.engagement_id=mil.engagement_id and q.id=(p_input->>'request_id')::uuid and q.state in ('approved','executing','verifying','complete') and exists(select 1 from wm.revisions proof where proof.organization_id=p_org and proof.id=q.current_revision_id and proof.manifest->>'milestone_id'=mil.id::text) and not exists(select 1 from wm.agreements contract where contract.organization_id=p_org and contract.request_id=q.id) and exists(select 1 from wm.decisions d where d.organization_id=p_org and d.revision_id=q.current_revision_id and d.decision='approve')) then raise exception 'Current approved work required' using errcode='42501';end if;
   if mil.proof_kind='readiness' and exists(select 1 from wm.access_requirements where organization_id=p_org and engagement_id=mil.engagement_id and status<>'verified') then raise exception 'Complete the account readiness checks first' using errcode='42501';end if;
   if mil.proof_kind='verified_launch' and not exists(select 1 from wm.operations where organization_id=p_org and engagement_id=mil.engagement_id and kind in ('google_enable','meta_enable','microsoft_enable','tiktok_enable','linkedin_enable') and state='verified') then raise exception 'Verified campaign launch evidence required' using errcode='42501';end if;
   update wm.milestones set status='accepted',earned_minor=amount_minor,evidence=p_input->>'evidence',evidence_request_id=(p_input->>'request_id')::uuid,version=version+1 where organization_id=p_org and id=mil.id returning id,version into rid,v;
   perform wm.critical(p_org,'milestone.earned',mil.id,jsonb_build_object('amount_minor',mil.amount_minor,'evidence',p_input->>'evidence','request_id',p_input->>'request_id'));
  end if;
 else raise exception 'Unknown commercial action' using errcode='22023';end if;
 return wm.finish_command(p_org,p_command,p_key,p_input,jsonb_build_object('id',rid,'version',v,'receipt_id',receipt),rid);
end $$;

-- Agreements have their own consent and schedule transition. Generic review
-- cannot bypass it or turn a contract withdrawal into an untracked termination.
alter function public.wm_decision_record(uuid,jsonb,text) rename to wm_decision_before_commercial;
revoke all on function public.wm_decision_before_commercial(uuid,jsonb,text) from public,anon,authenticated;
create function public.wm_decision_record(p_org uuid,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
begin
 perform wm.require_access(p_org,'write');
 if exists(select 1 from wm.revisions where organization_id=p_org and id=(p_input->>'revision_id')::uuid and kind='agreement') then raise exception 'Use the agreement acceptance or service closure action' using errcode='22023';end if;
 return public.wm_decision_before_commercial(p_org,p_input,p_key);
end $$;
alter function public.wm_revision_create(uuid,jsonb,text) rename to wm_revision_before_commercial;
revoke all on function public.wm_revision_before_commercial(uuid,jsonb,text) from public,anon,authenticated;
create function public.wm_revision_create(p_org uuid,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare linked wm.milestones;
begin
 perform wm.require_access(p_org,'delivery');
 if p_input->>'kind'='agreement' or exists(select 1 from wm.agreements where organization_id=p_org and request_id=(p_input->>'request_id')::uuid) then raise exception 'Prepare a new proposal or amendment' using errcode='22023';end if;
 select * into linked from wm.milestones where organization_id=p_org and evidence_request_id=(p_input->>'request_id')::uuid;
 if found then p_input:=jsonb_set(p_input,'{manifest}',coalesce(p_input->'manifest','{}')||jsonb_build_object('milestone_id',linked.id,'milestone_acceptance',linked.acceptance_rule));end if;
 return public.wm_revision_before_commercial(p_org,p_input,p_key);
end $$;

alter function public.wm_workspace(uuid) rename to wm_workspace_before_commercial;
revoke all on function public.wm_workspace_before_commercial(uuid) from public,anon,authenticated;
create function public.wm_workspace(p_org uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare result jsonb; finance boolean;
begin
 result:=public.wm_workspace_before_commercial(p_org);finance:=wm.operator_has(p_org,'finance') or wm.member_role(p_org)='customer_admin';
 result:=result||jsonb_build_object('agreements',(select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('manifest',r.manifest,'digest',r.digest) order by a.created_at desc),'[]') from wm.agreements a join wm.revisions r on r.organization_id=p_org and r.id=a.revision_id where a.organization_id=p_org and (wm.operator_has(p_org,'finance') or (a.sent_at is not null and (finance or exists(select 1 from wm.engagement_authorities z where z.organization_id=p_org and z.engagement_id=a.engagement_id and z.user_id=auth.uid() and z.domain='contract' and z.revoked_at is null and z.starts_at<=now() and z.ends_at>now()))))),
 'milestones',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from wm.milestones x where x.organization_id=p_org and finance),
 'catalog',case when wm.operator_has(p_org,'finance') then (select coalesce(jsonb_agg(snapshot order by catalog_id,variant),'[]') from wm.catalog_registry) else '[]'::jsonb end);
 -- Draft commercial records and financial manifests are absent for readers
 -- without a current financial or contract role, including generic review views.
 result:=jsonb_set(result,'{requests}',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(result->'requests') x where not exists(select 1 from wm.agreements a where a.organization_id=p_org and a.request_id=(x->>'id')::uuid) or exists(select 1 from jsonb_array_elements(result->'agreements') a where a->>'request_id'=x->>'id')));
 result:=jsonb_set(result,'{revisions}',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(result->'revisions') x where x->>'kind'<>'agreement' or exists(select 1 from jsonb_array_elements(result->'agreements') a where a->>'revision_id'=x->>'id')));
 result:=jsonb_set(result,'{decisions}',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(result->'decisions') x where exists(select 1 from jsonb_array_elements(result->'revisions') r where r->>'id'=x->>'revision_id')));
 return result;
end $$;
create function public.wm_agreement_receipt(p_org uuid,p_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare data jsonb;agreement jsonb;
begin
 data:=public.wm_workspace(p_org);
 select x into agreement from jsonb_array_elements(data->'agreements') x where x->>'id'=p_id::text and x->>'accepted_at' is not null;
 if agreement is null then raise exception 'Acceptance receipt unavailable' using errcode='42501';end if;
 return jsonb_build_object('schema',1,'business',data->'business','agreement',agreement,'consent','Affirmative acceptance of the exact scope, fees and terms','decision',(select to_jsonb(d) from wm.decisions d where d.organization_id=p_org and d.id=(agreement->>'accepted_decision_id')::uuid),'receipt',(select jsonb_build_object('id',c.id,'digest',c.digest,'sequence',c.sequence,'durability',c.durability_status) from wm.critical_receipts c where c.organization_id=p_org and c.event_type='agreement.accepted' and c.target_id=p_id));
end $$;
revoke all on function public.wm_agreement_receipt(uuid,uuid) from public,anon;
grant execute on function public.wm_agreement_receipt(uuid,uuid) to authenticated;
revoke all on function public.wm_commercial_command(uuid,text,jsonb,text),public.wm_workspace(uuid),public.wm_decision_record(uuid,jsonb,text),public.wm_revision_create(uuid,jsonb,text) from public,anon;
grant execute on function public.wm_commercial_command(uuid,text,jsonb,text),public.wm_workspace(uuid),public.wm_decision_record(uuid,jsonb,text),public.wm_revision_create(uuid,jsonb,text) to authenticated;
revoke all on all functions in schema wm from public,anon,authenticated;
insert into wm.catalog_registry(catalog_id,variant,catalog_version,snapshot,digest) select s->>'id',s->>'variant',s->>'catalog_version',s,wm.hash_json(s) from (values('{"schema":1,"id":"launch_site","variant":"standard","name":"Focused Website","service_type":"web_design","catalog_version":"2026-10-29-v4-offers","currency":"USD","scope":"Structured written intake, one audience, one primary inquiry journey and a ten-page plan. Review up to two relevant competitors. An optional 30-minute kickoff can replace the written kickoff. Up to 10 marketing pages with original AI-assisted writing, edited and checked against approved business facts. Content is as concise or detailed as the topic, reader and search intent require; there is no word quota or word-count surcharge for the agreed page purpose. Select and adapt one established W&M layout direction. Apply the client’s logo, colors, typography, spacing and imagery consistently. The client sees the design approach before booking; a newly art-directed visual system is a Custom Website scope. Prepare up to eight supplied/licensed photographs and one simple original website graphic. No original logo, commissioned photography or motion production. One contact form with up to eight fields, one notification destination, spam controls and confirmation; one existing booking/payment tool link or embed. New provider configuration and automations are separate. One agreed supported platform. If needed, one standard content collection with up to six supplied entries using the established component set. Up to three client-supplied policy pages are formatted outside the 10 marketing-page count. Two consolidated review rounds: copy/design direction, then complete preview. Shared launch checks, audit/check record and explicit launch approval. Written editing guide and recorded demonstration; optional 20-minute handoff appointment. Client-controlled domain and service accounts, an ownership/license inventory, checks within two business days and around day 14 after launch, and 30-day defect support. Optional Care is separate. Search-ready page planning: map each agreed service or buyer question to its page; review search intent and relevant query themes, write unique titles/descriptions, connect related pages with internal links, and apply the shared technical search checks. Search demand informs useful content; rankings are not guaranteed. Written communication by default: email or the agreed text channel anytime, with acknowledgement within one business day during active delivery/support. Weekly project updates; optional calls by appointment. No call is required to buy, give feedback or receive the handoff. Launch handover pack: page and account inventory, test/check record, editing guide with recorded demonstration, support dates, and a prioritized next-90-days recommendation sheet. This is a handoff recommendation, not ongoing SEO delivery or a new full audit. Basic inquiry measurement: connect one client-owned GA4 property and Search Console property, and test page views plus one primary inquiry-success event through a supported native integration. Configure one compatible consent tool using client-approved settings where required; its subscription is a disclosed client cost. Excludes GTM/custom tagging, dashboards, cross-domain/server-side tracking and extra events. Confirm platform feasibility before booking; no silent omission if unavailable. Preserve existing working measurement and avoid duplicates.","exclusions":["A new visual identity, original art direction or multiple homepage concepts","Store, portal, custom calculator, conditional form, migration or custom application","New tool-account setup beyond the included basic measurement, original field research, ongoing SEO, social media and advertising"],"acceptance":["All agreed pages, approved copy and supplied policy text are complete.","The selected design approach is consistent across mobile and desktop.","The shared quality checks and audit record are complete, including a tested inquiry destination and confirmation.","The owner explicitly approves launch and receives access, responsibilities and handoff."],"components":[],"milestones":[{"id":"stage_1","deliverable":"Reserve your agreed start","amount_minor":87800,"acceptance_rule":"Reserve your agreed start","proof":"booking"},{"id":"stage_2","deliverable":"Approve copy and design direction","amount_minor":65850,"acceptance_rule":"Approve copy and design direction","proof":"approved_work"},{"id":"stage_3","deliverable":"Approve staging before launch","amount_minor":65850,"acceptance_rule":"Approve staging before launch","proof":"approved_work"}],"entitlements":[],"quote_required":false,"hosting_offset_cap_minor":0,"terms":{"delivery":"Delivery begins at your ready, booked start: approved scope, initial payment, access and business facts in place. The next available start is confirmed separately. Normal review time is included; allow two business days for consolidated feedback at each gate. The shortest targets need prompt approvals. Missing inputs or approved changes can move dates. Written communication is standard; calls are optional.","payment":"Reserve your agreed start: 878.00 USD; Approve copy and design direction: 658.50 USD; Approve staging before launch: 658.50 USD","cancellation":"Use a written reconciliation: pay for completed agreed work and approved nonrecoverable external expenses; return unearned prepaid fees. Define the reconciliation and payment timetable in the proposal instead of calling every deposit nonrefundable. Existing client agreements keep their terms.","ownership":"The client owns the domain and business/platform accounts from the beginning where the provider supports it; W&M uses delegated access. Client-owned pre-existing accounts and data are never withheld as a substitute for collecting a disputed invoice. Transfer agreed original deliverables and editable source files under the project agreement after the relevant fees are paid. Identify licensed fonts, stock media, open-source components, third-party platform restrictions and AI-assisted assets separately. Do not promise exclusive ownership of licensed or generated material.","overlap":"Choose one production plan per site. Production-only is available for a healthy supported site with maintenance handled elsewhere. Brochure Care adds $100/month; Commerce replaces it for another $146/month. Never bill both Care variants or a second standalone Care fee.","onboarding":"Care onboarding is $195 for Brochure or $395 for Commerce. It is waived immediately after a W&M build with the same complete handoff, and for the first three approved introductory monthly production clients who select Care. Standalone Care retains its onboarding fee. The full compatibility, access, monitoring and recovery checks still apply. Production-only plans have no Care onboarding charge; a pre-start fit and access review is included. Any remediation is agreed separately before acceptance. Eligibility and the exact first invoice are confirmed before payment.","measurement":"The first paid production cycle includes missing supported native GA4 and Search Console setup plus one inquiry-success event, using client-approved consent settings. Working measurement is reused. There is no separate fee for this basic setup; advanced tagging or dashboards need an incremental quote. If native setup is unavailable, agree an equivalent or revised scope before payment. The cycle still includes all promised production outputs."},"required_facts":["business_identity","service_goals","approved_claims","primary_contact"],"required_access":["domain","website"]}'::jsonb)) seed(s);
