insert into wm.catalog_registry(catalog_id,variant,catalog_version,snapshot,digest) select s->>'id',s->>'variant',s->>'catalog_version',s,wm.hash_json(s) from (values('{"schema":1,"id":"audit_fix_sprint","variant":"standard","name":"Website Repair Sprint","service_type":"catalog_project","catalog_version":"2026-10-29-v4-offers","currency":"USD","scope":"A short access/platform check, written scope confirmation and reproduction of the reported problems; optional 45-minute scope appointment. Agree up to three bounded fixes before booking. The total implementation work must fit six planned production hours; preparation, testing, communication and contingency are budgeted separately. Typical eligible fixes: correct a form delivery/confirmation path; fix a mobile layout issue in one shared component; optimize specified first-party images/fonts; repair agreed metadata/indexability settings; or rewrite and implement one existing page for its agreed purpose. Create a backup or rollback path before changes. Use a preview/staging environment when the platform supports it. Implement the exact accepted fix list, run the defined checks, and provide a change log and before/after evidence. One consolidated preview-feedback round and written/recorded handoff; optional 30-minute appointment. W&M-caused defects are corrected without consuming a paid addition.","exclusions":["A whole-site redesign, unbounded speed cleanup or guaranteed Lighthouse score","Malware recovery, unsupported legacy plugins, major migrations or custom application repair","New checkout, complex integrations, third-party outages or recovery of inaccessible accounts"],"acceptance":["Each agreed fix passes its written before/after check.","Changed forms are tested through receipt and confirmation, not just the submit button.","No identified material regression in the touched pages or shared components."],"components":[],"milestones":[{"id":"stage_1","deliverable":"Book the agreed scope","amount_minor":42450,"acceptance_rule":"Book the agreed scope","proof":"booking"},{"id":"stage_2","deliverable":"Accept the agreed deliverables","amount_minor":42450,"acceptance_rule":"Accept the agreed deliverables","proof":"approved_work"}],"entitlements":[],"quote_required":false,"hosting_offset_cap_minor":0,"terms":{"delivery":"Delivery begins at your ready, booked start: approved scope, initial payment, access and business facts in place. The next available start is confirmed separately. Normal review time is included; allow two business days for consolidated feedback at each gate. The shortest targets need prompt approvals. Missing inputs or approved changes can move dates. Written communication is standard; calls are optional.","payment":"Book the agreed scope: 424.50 USD; Accept the agreed deliverables: 424.50 USD","cancellation":"Use a written reconciliation: pay for completed agreed work and approved nonrecoverable external expenses; return unearned prepaid fees. Define the reconciliation and payment timetable in the proposal instead of calling every deposit nonrefundable. Existing client agreements keep their terms.","ownership":"The client owns the domain and business/platform accounts from the beginning where the provider supports it; W&M uses delegated access. Client-owned pre-existing accounts and data are never withheld as a substitute for collecting a disputed invoice. Transfer agreed original deliverables and editable source files under the project agreement after the relevant fees are paid. Identify licensed fonts, stock media, open-source components, third-party platform restrictions and AI-assisted assets separately. Do not promise exclusive ownership of licensed or generated material.","overlap":"Choose one production plan per site. Production-only is available for a healthy supported site with maintenance handled elsewhere. Brochure Care adds $100/month; Commerce replaces it for another $146/month. Never bill both Care variants or a second standalone Care fee.","onboarding":"Care onboarding is $195 for Brochure or $395 for Commerce. It is waived immediately after a W&M build with the same complete handoff, and for the first three approved introductory monthly production clients who select Care. Standalone Care retains its onboarding fee. The full compatibility, access, monitoring and recovery checks still apply. Production-only plans have no Care onboarding charge; a pre-start fit and access review is included. Any remediation is agreed separately before acceptance. Eligibility and the exact first invoice are confirmed before payment.","measurement":"The first paid production cycle includes missing supported native GA4 and Search Console setup plus one inquiry-success event, using client-approved consent settings. Working measurement is reused. There is no separate fee for this basic setup; advanced tagging or dashboards need an incremental quote. If native setup is unavailable, agree an equivalent or revised scope before payment. The cycle still includes all promised production outputs."},"required_facts":["business_identity","service_goals","approved_claims","primary_contact"],"required_access":[]}'::jsonb)) seed(s);
insert into wm.catalog_registry(catalog_id,variant,catalog_version,snapshot,digest) select s->>'id',s->>'variant',s->>'catalog_version',s,wm.hash_json(s) from (values('{"schema":1,"id":"keep_running","variant":"brochure","name":"Website Care","service_type":"care","catalog_version":"2026-10-29-v4-offers","currency":"USD","scope":["Brochure Care: $149/month for one brochure/service website, up to 30 maintained marketing pages and up to three ordinary inquiry journeys.","Commerce Care: $295/month for one supported straightforward store, up to 100 products, one checkout and up to three ordinary inquiry journeys. Platform/app limits remain as documented at onboarding.","Automated availability monitoring at least every 15 minutes, with alerts to W&M during business hours; no promise of continuous human attendance.","One monthly manual mobile/desktop check of the homepage, navigation, up to three agreed forms/inquiry paths. Commerce includes a supported checkout/order-notification test.","One planned maintenance window per month: test supported first-party dependencies or WordPress updates in staging; vendor-hosted platforms use the responsibilities table instead.","A documented backup/recovery setup and quarterly representative restore/rollback test appropriate to the platform. Confirm exactly which data are covered.","One batch of supplied text/image edits up to 60 minutes for either Brochure Care or Commerce Care. No new page design or original copywriting.","A monthly work log, exception list and next action. Support acknowledgement within one business day; site-down or failed-checkout reports are triaged within one business day during business hours.","Brochure scope includes the ordinary forms and up to two show/hide field groups supplied by the website tiers. A three-journey Signature site can enter this Care scope after its compatible handoff. Custom apps, scoring and calculations remain excluded.","Brochure Care, standalone or bundled, includes an offset for up to $25/month of eligible supported hosting. Client owns/pays the hosting account; deduct its documented actual monthly hosting fee, capped at $25, from the W&M invoice. A $299 bundle with $20 hosting means $279 to W&M plus $20 to the host; $50 hosting means $274 plus $50, total $324. No hosting bill means no offset. Domains, platform licenses, apps, taxes and other vendor charges remain separate. Commerce receives no hosting offset; its store/platform costs are disclosed separately."],"exclusions":["24/7 response, guaranteed uptime, unlimited repairs or a security guarantee","Malware remediation, major version migrations, abandoned plugins, new features or recovery of third-party services","Custom applications, portals, complex stores, regulated-data systems or fulfillment operations"],"acceptance":["Each monthly report identifies checks performed, work completed and unresolved exceptions.","The recovery method is tested for the components it claims to cover.","Edits and maintenance are checked before/after; provider-caused regressions are corrected.","Outside-cost and support boundaries remain visible."],"components":[{"id":"management","amount_minor":14900,"interval":"month","trigger":"service_start"},{"id":"care_onboarding","amount_minor":19500,"interval":"once","trigger":"acceptance","waiver":"post_wm_build_or_first_three_intro_production_clients"}],"milestones":[],"entitlements":[{"kind":"care_edits","quantity":60,"unit":"minutes","period":"month","rollover_policy":"none"}],"quote_required":false,"hosting_offset_cap_minor":2500,"terms":{"delivery":"Delivery begins at your ready, booked start: approved scope, initial payment, access and business facts in place. The next available start is confirmed separately. Normal review time is included; allow two business days for consolidated feedback at each gate. The shortest targets need prompt approvals. Missing inputs or approved changes can move dates. Written communication is standard; calls are optional.","payment":"Your accepted fixed project keeps its written price and scope. One month is billed in advance. Cancel before the next billing date to stop the next cycle. Monthly clients keep the quoted fee for their first three paid cycles. After that, the same fee continues until a written change has at least 30 days notice. There is no automatic price increase or annual lock-in. Availability is confirmed against actual delivery capacity before booking.","cancellation":"Your paid custom files and content, and your own accounts, remain yours under the listed licenses and provider export limits. Your provider subscriptions continue or cancel as you instruct. I still owe unfinished work you approved. Delivery of existing paid files is included; new migration work needs a separate quote. An unrelated unpaid service invoice cannot justify disabling paid client work.","ownership":"The client owns the domain and business/platform accounts from the beginning where the provider supports it; W&M uses delegated access. Client-owned pre-existing accounts and data are never withheld as a substitute for collecting a disputed invoice. Transfer agreed original deliverables and editable source files under the project agreement after the relevant fees are paid. Identify licensed fonts, stock media, open-source components, third-party platform restrictions and AI-assisted assets separately. Do not promise exclusive ownership of licensed or generated material.","overlap":"Choose one production plan per site. Production-only is available for a healthy supported site with maintenance handled elsewhere. Brochure Care adds $100/month; Commerce replaces it for another $146/month. Never bill both Care variants or a second standalone Care fee.","onboarding":"Care onboarding is $195 for Brochure or $395 for Commerce. It is waived immediately after a W&M build with the same complete handoff, and for the first three approved introductory monthly production clients who select Care. Standalone Care retains its onboarding fee. The full compatibility, access, monitoring and recovery checks still apply. Production-only plans have no Care onboarding charge; a pre-start fit and access review is included. Any remediation is agreed separately before acceptance. Eligibility and the exact first invoice are confirmed before payment.","measurement":"The first paid production cycle includes missing supported native GA4 and Search Console setup plus one inquiry-success event, using client-approved consent settings. Working measurement is reused. There is no separate fee for this basic setup; advanced tagging or dashboards need an incremental quote. If native setup is unavailable, agree an equivalent or revised scope before payment. The cycle still includes all promised production outputs."},"required_facts":["business_identity","service_goals","approved_claims","primary_contact"],"required_access":["website","hosting_recovery"]}'::jsonb)) seed(s);
