insert into wm.catalog_registry(catalog_id,variant,catalog_version,snapshot,digest) select s->>'id',s->>'variant',s->>'catalog_version',s,wm.hash_json(s) from (values('{"schema":1,"id":"grow","variant":"production","name":"Local Search Partnership","service_type":"seo","catalog_version":"2026-10-29-v4-offers","currency":"USD","scope":["One location and one primary service market; up to 30 supported marketing pages. $349/month production only, $449 with Brochure Care or $595 with Commerce Care. Supported stores receive service/information-page work, not product/category ecommerce SEO.","An initial 90-day topic and local-presence plan; monthly Search Console/GA4/profile review where data are available. Track up to 10 agreed non-branded query themes, without presenting unstable ranking checks as guaranteed results.","Five new researched articles or useful service pages each month, using the existing supported design and publishing setup. Each answers one agreed buyer question or service purpose. Content length follows the topic, reader and search intent, without a fixed word quota. Each complete article counts once; research, publishing and checks are not separate deliverables.","Each article includes topic and search-intent research, original writing from checked sources and client expertise, factual review, page title and headings, relevant internal links, publishing, and readability/mobile/link checks. One consolidated client review round is included. Client-specific claims and proof need approval before publication.","Monthly accuracy review of one Google Business Profile; up to five simple data/service/hour updates and up to five owner-approved review-reply drafts where there are reviews to answer.","Check up to five agreed priority business listings; submit up to one correction where access permits. Submissions and approvals are reported separately.","A written monthly strategy review (or optional 30-minute appointment) and report on completed work, available impressions/clicks/inquiries, attribution limits and next priorities.","Write and publish up to two short owner-approved Google profile update posts monthly, using existing approved facts/assets. This replaces the former conditional outreach/substitute-listing activity.","One additional bounded conversion improvement: refine one call-to-action section, confirmation message or existing ordinary form/journey component. Agree one specific acceptance check; implement and regression-test it within the existing design. No new integration, calculator, page or A/B-test campaign. This is additional to all five articles.","When Brochure Care is selected, the shared hosting-offset rule covers up to $25/month of documented eligible hosting. Commerce and production-only variants have no hosting offset.","For the first three approved introductory production clients, Care onboarding is included when Care is chosen. The first cycle also includes missing supported native GA4/Search Console setup and one inquiry event; advanced measurement remains separate. All production outputs are still due in that paid cycle.","Before renewal, check whether the next five pages exceed supported limits. Agree any scope or fee expansion before payment, or do not renew. Every accepted cycle still includes all five outputs. Care keeps its separate coverage limits."],"exclusions":["Multiple locations, national SEO, large ecommerce SEO or unlimited pages","Bulk/paid links, guaranteed rankings, review incentives or guaranteed lead/revenue increases","Social content calendars, multi-channel posting campaigns, advertising and email campaigns","Link outreach is excluded from this revised package. It is not quietly retained alongside the lower price.","New publishing platforms, custom page templates, original field research, specialist professional verification or custom interactive features. Agree separate work before accepting it; do not silently reduce the five included articles."],"acceptance":["Five distinct, complete articles or service pages are approved, published and checked. A report lists their URLs, the question each answers and completed checks; one page cannot be counted twice. An existing-page refresh or technical repair replaces an article only with explicit written agreement.","Local profile/listing changes, submissions and posts are logged with submitted/approved status.","Reports distinguish search signals and inquiries from proven causation.","When Care is selected, Care is performed and duplicate care billing is prevented.","The additional agreed conversion change passes its acceptance check; it is not counted as a content/SEO unit."],"components":[{"id":"management","amount_minor":34900,"interval":"month","trigger":"service_start"}],"milestones":[],"entitlements":[],"quote_required":false,"hosting_offset_cap_minor":0,"terms":{"delivery":"Delivery begins at your ready, booked start: approved scope, initial payment, access and business facts in place. The next available start is confirmed separately. Normal review time is included; allow two business days for consolidated feedback at each gate. The shortest targets need prompt approvals. Missing inputs or approved changes can move dates. Written communication is standard; calls are optional.","payment":"Your accepted fixed project keeps its written price and scope. One month is billed in advance. Cancel before the next billing date to stop the next cycle. Monthly clients keep the quoted fee for their first three paid cycles. After that, the same fee continues until a written change has at least 30 days notice. There is no automatic price increase or annual lock-in. Availability is confirmed against actual delivery capacity before booking.","cancellation":"Your paid custom files and content, and your own accounts, remain yours under the listed licenses and provider export limits. Your provider subscriptions continue or cancel as you instruct. I still owe unfinished work you approved. Delivery of existing paid files is included; new migration work needs a separate quote. An unrelated unpaid service invoice cannot justify disabling paid client work.","ownership":"The client owns the domain and business/platform accounts from the beginning where the provider supports it; W&M uses delegated access. Client-owned pre-existing accounts and data are never withheld as a substitute for collecting a disputed invoice. Transfer agreed original deliverables and editable source files under the project agreement after the relevant fees are paid. Identify licensed fonts, stock media, open-source components, third-party platform restrictions and AI-assisted assets separately. Do not promise exclusive ownership of licensed or generated material.","overlap":"Choose one production plan per site. Production-only is available for a healthy supported site with maintenance handled elsewhere. Brochure Care adds $100/month; Commerce replaces it for another $146/month. Never bill both Care variants or a second standalone Care fee.","onboarding":"Care onboarding is $195 for Brochure or $395 for Commerce. It is waived immediately after a W&M build with the same complete handoff, and for the first three approved introductory monthly production clients who select Care. Standalone Care retains its onboarding fee. The full compatibility, access, monitoring and recovery checks still apply. Production-only plans have no Care onboarding charge; a pre-start fit and access review is included. Any remediation is agreed separately before acceptance. Eligibility and the exact first invoice are confirmed before payment.","measurement":"The first paid production cycle includes missing supported native GA4 and Search Console setup plus one inquiry-success event, using client-approved consent settings. Working measurement is reused. There is no separate fee for this basic setup; advanced tagging or dashboards need an incremental quote. If native setup is unavailable, agree an equivalent or revised scope before payment. The cycle still includes all promised production outputs."},"required_facts":["business_identity","service_goals","approved_claims","primary_contact"],"required_access":["website","search_console","analytics"]}'::jsonb)) seed(s);
